mapper.select:
SELECT
    p.*
FROM elder_profile p

    p.deleted = 0

        AND p.name LIKE CONCAT('%', #{query.name}, '%')


        AND p.id_card = #{query.idCard}


        AND p.phone LIKE CONCAT('%', #{query.phone}, '%')


        AND p.living_type = #{query.livingType}


        AND EXISTS (
            SELECT 1 FROM elder_tag_relation r
            WHERE r.elder_id = p.id AND r.tag_id = #{query.tagId}
        )


ORDER BY p.create_time DESC
